    sell_book = []  # list of (price, arrival_time, id, qty)
    order_map = {}  # id -> (side, price, arrival_time)
    arrival_time = 0

    for order in orders:
        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, price, arr_time = order_map[order_id]
                del order_map[order_id]
                if side == 'buy':
                    buy_book = [(p, t, oid, q) for p, t, oid, q in buy_book if oid != order_id]
